```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int rosnace = 0, malejace = 0;
    int maxDl = 1, maxStart = 0, maxKier = 0;
    int curDl = 1, curStart = 0, curKier = 0;

    for (int i = 1; i < n; i++) {
        int nowyKier = 0;
        if (T[i] > T[i - 1]) nowyKier = 1;
        else if (T[i] < T[i - 1]) nowyKier = -1;
        else nowyKier = 0;

        if (nowyKier == 0 || (curKier != 0 && nowyKier != curKier)) {
            if (curKier == 1) rosnace++;
            else if (curKier == -1) malejace++;
            if (curDl > maxDl && curKier != 0) {
                maxDl = curDl; maxStart = curStart; maxKier = curKier;
            }
            if (nowyKier == 0) {
                curDl = 1; curStart = i; curKier = 0;
            } else {
                curDl = 2; curStart = i - 1; curKier = nowyKier;
            }
        } else if (curKier == 0) {
            curKier = nowyKier;
            curDl = 2;
            curStart = i - 1;
        } else {
            curDl++;
        }
    }
    if (curKier == 1) rosnace++;
    else if (curKier == -1) malejace++;
    if (curDl > maxDl && curKier != 0) {
        maxDl = curDl; maxStart = curStart; maxKier = curKier;
    }

    cout << "a) Rosnace: " << rosnace << ", Malejace: " << malejace << endl;
    cout << endl << "b) Najdluzszy segment:" << endl;
    cout << "   Typ: " << (maxKier == 1 ? "rosnacy" : "malejacy")
         << ", dlugosc: " << maxDl
         << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    cout << "   Elementy:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Sledzenie kierunku monotonicznosci. Kazda zmiana kierunku lub para rownych elementow konczy biezacy segment.

Weryfikacja (dane: 3,5,8,12,7,4,2,6,9,11,15,14,10,10,13,17,20,16):
Indeksy 0-based: T[0]=3..T[17]=16.
Segmenty:
1. Rosnacy: T[0..3] = 3,5,8,12 (dl.4, poz.1). Koniec: T[4]=7 < T[3]=12.
2. Malejacy: T[3..6] = 12,7,4,2 (dl.4, poz.4). Koniec: T[7]=6 > T[6]=2.
3. Rosnacy: T[6..10] = 2,6,9,11,15 (dl.5, poz.7). Koniec: T[11]=14 < T[10]=15.
4. Malejacy: T[10..12] = 15,14,10 (dl.3, poz.11). Koniec: T[13]=10 == T[12]=10.
5. (T[13]=10, curKier=0). T[14]=13 > T[13]=10 -> rosnacy.
   Rosnacy: T[13..16] = 10,13,17,20 (dl.4, poz.14). Koniec: T[17]=16 < T[16]=20.
6. Malejacy: T[16..17] = 20,16 (dl.2, poz.17). Koniec petli.
Rosnace: 1,3,5 -> 3. Malejace: 2,4,6 -> 3.
